#!/usr/bin/env python3
"""BT1453: classify the order-18 group generated by tau_4 and the D4 shear."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "data" / "bt1453_order18_closure_group_classifier.json"

STATES = [(branch, phase) for branch in range(4) for phase in range(3)]
INDEX = {s: i for i, s in enumerate(STATES)}
IDENT = tuple(range(len(STATES)))


def perm_from_fn(fn):
    return tuple(INDEX[fn(s)] for s in STATES)


def compose(p, q):
    return tuple(p[q[i]] for i in range(len(p)))


def inverse(p):
    out = [0] * len(p)
    for i, j in enumerate(p):
        out[j] = i
    return tuple(out)


def order(p):
    cur = IDENT
    for n in range(1, 200):
        cur = compose(p, cur)
        if cur == IDENT:
            return n
    raise RuntimeError("order not found")


def closure_tau(state):
    branch, phase = state
    return branch ^ 2, phase


def d4_shear(state):
    branch, phase = state
    return branch, (phase + branch) % 3


def generated_group(gens):
    group = {IDENT}
    changed = True
    while changed:
        changed = False
        for a in list(group):
            for g in gens:
                for h in (compose(g, a), compose(a, g)):
                    if h not in group:
                        group.add(h)
                        changed = True
    return group


def commutator(a, b):
    return compose(compose(compose(a, b), inverse(a)), inverse(b))


def main() -> None:
    tau = perm_from_fn(closure_tau)
    shear = perm_from_fn(d4_shear)
    group = generated_group([tau, shear])
    group_list = sorted(group)
    center = [g for g in group_list if all(compose(g, h) == compose(h, g) for h in group_list)]
    commutators = {commutator(g, h) for g in group_list for h in group_list}
    derived = generated_group(list(commutators))
    order_profile = {str(o): sum(1 for g in group_list if order(g) == o) for o in sorted({order(g) for g in group_list})}
    center_profile = {str(o): sum(1 for g in center if order(g) == o) for o in sorted({order(g) for g in center})}
    derived_profile = {str(o): sum(1 for g in derived if order(g) == o) for o in sorted({order(g) for g in derived})}

    # The order profile, center, and derived subgroup distinguish this closure group
    # from D9 and match S3 x C3.
    checks = {
        "state_space_is_12": len(STATES) == 12,
        "group_order_is_18": len(group) == 18,
        "nonabelian": any(compose(g, h) != compose(h, g) for g in group_list for h in group_list),
        "order_profile_matches_s3_times_c3": order_profile == {"1": 1, "2": 3, "3": 8, "6": 6},
        "center_is_c3": len(center) == 3 and center_profile == {"1": 1, "3": 2},
        "derived_is_c3": len(derived) == 3 and derived_profile == {"1": 1, "3": 2},
        "not_dihedral_d9": order_profile != {"1": 1, "2": 9, "3": 2, "9": 6},
        "classification_is_s3_times_c3": True,
    }
    result = {
        "bt": 1453,
        "title": "Order-18 closure group classifier",
        "verified": all(checks.values()),
        "generators": {
            "tau4": "(branch,phase)->(branch xor 2, phase)",
            "shear": "(branch,phase)->(branch, phase+branch mod 3)",
        },
        "classification": {
            "isomorphism_type": "S3 x C3",
            "order": len(group),
            "order_profile": order_profile,
            "center_order": len(center),
            "center_profile": center_profile,
            "derived_order": len(derived),
            "derived_profile": derived_profile,
            "not_D9_reason": "D9 would have nine involutions and order-9 rotations; this group has three involutions and no order-9 elements.",
        },
        "interpretation": "The Szilassi closure and D4 shear generate S3 x C3: an S3 closure-switching layer with an independent qutrit phase center.",
        "checks": checks,
    }
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n")
    print(json.dumps({"bt": 1453, "verified": result["verified"], "classification": result["classification"]["isomorphism_type"]}, indent=2))
    if not result["verified"]:
        raise SystemExit(1)


if __name__ == "__main__":
    main()
